d_uv += vec2(dx.x,dy.x)*0.03;
ret = mix(GetBlur2(d_uv),GetPixel(d_uv),0.4);
ret = (ret.y-ret.x*0.5)*mix(vec3(.2,0.7,1.25), 1.0 ,ret.x)*1.4;
vec4 noise9 = tex3D(sampler_noisevol_hq,
((d_uv.xyy*q28
)*uTexSize.xyy*texsize_noisevol_hq.zww
).xyz*
vec3( 1.0 , 1.0 , 0.0 )*0.05 +
uTime*vec3( 0.0 , 0.0 , 1.0 )*q31
);
if(ret.x> q26*q13         && ret.x<= q23*q11        )ret.z -= (noise9).x*.5;
if(ret.y> q25*q11         && ret.y<= q22*q12        )ret.x -= (noise9).y*.5;
if(ret.z> q24*q12         && ret.z<= q21*q13        )ret.y -= (noise9).z*.5;
ret = mix(ret,vec3(-0.1,-0.1,.1),GetBlur1(d_uv-vec2( 1.0 , 1.0)*(vec2(1.0)/uTexSize) * 32.0).z*0.6);
ret = mix(ret,vec3(1.5,1.5, 2.0),GetPixel(uv_o).z*0.36);
//ret = GetPixel(uv);
}
  fragColor = vec4(ret, 1.0);
}

